import csv
import io
import re


def parse_csv(raw_csv: str):
    expected_width = 10
    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
        strict=False,
    )
    parsed = [row for row in reader if row and any(cell != "" for cell in row)]

    if not parsed:
        return {"columns": [], "rows": []}

    label_pattern = re.compile(r"^[A-Za-z][A-Za-z0-9 _-]*$")
    header_index = None

    for index, row in enumerate(parsed):
        if len(row) != expected_width:
            continue
        normalized = [cell.strip().lower() for cell in row]
        if (
            all(cell and label_pattern.fullmatch(cell) for cell in row)
            and len(set(normalized)) == len(normalized)
        ):
            header_index = index
            break

    if header_index is None:
        header_index = next(
            (i for i, row in enumerate(parsed) if len(row) == expected_width),
            0,
        )

    columns = list(parsed[header_index])
    if len(columns) > expected_width:
        columns = columns[: expected_width - 1] + [
            ",".join(columns[expected_width - 1 :])
        ]
    elif len(columns) < expected_width:
        columns.extend([""] * (expected_width - len(columns)))

    rows = []
    for row in parsed[header_index + 1 :]:
        if len(row) > expected_width:
            row = row[: expected_width - 1] + [
                ",".join(row[expected_width - 1 :])
            ]
        elif len(row) < expected_width:
            row = row + [""] * (expected_width - len(row))
        rows.append(list(row))

    return {"columns": columns, "rows": rows}
